#!/bin/bash
# Provision the UE subscriber into free5GC through the WebUI REST API.
set -euo pipefail
NS=free5gc
SVC=$(kubectl -n $NS get svc -o name | grep webui | head -1)
DIR=$(cd "$(dirname "$0")" && pwd)
kubectl -n $NS port-forward "$SVC" 15000:5000 >/tmp/webui-pf.log 2>&1 &
PF=$!; trap 'kill $PF' EXIT; sleep 3
TOKEN=$(curl -sf -X POST http://127.0.0.1:15000/api/login -H 'Content-Type: application/json' \
        -d '{"username":"admin","password":"free5gc"}' | python3 -I -c 'import json,sys;print(json.load(sys.stdin)["access_token"])')
curl -s -w ' HTTP %{http_code}\n' -X POST http://127.0.0.1:15000/api/subscriber/imsi-208930000000001/20893 \
     -H 'Content-Type: application/json' -H "Token: $TOKEN" --data @"$DIR/subscriber-imsi-208930000000001.json"
echo "--- subscribers now in DB:"
curl -s http://127.0.0.1:15000/api/subscriber -H "Token: $TOKEN"; echo
EOF
chmod +x provision-subscriber.sh; kubectl -n free5gc get svc | grep webui; ./provision-subscriber.sh

